<?php
if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/billing-payments/')));exit;}$u=wp_get_current_user();$client=legacyx_find_client_by_wp_user(get_current_user_id());$rows=$client?legacyx_get_client_billing($client->ID):array();$counts=$client?legacyx_billing_counts($client->ID):array('total'=>0,'open'=>0,'paid'=>0,'balance'=>0,'paid_amount'=>0);get_header();?><main class="legacyx-credit-center"><div class="legacyx-credit-shell"><a class="legacyx-credit-back" href="<?php echo esc_url(home_url('/client-portal/'));?>">← Client Command Center</a><header class="legacyx-credit-head"><div><span class="kicker">LEGACY X FIRM OS · BILLING</span><h1>Billing & Payments</h1><p>Review engagement invoices, balances, payment history and authorized payment options connected to your Universal Client Profile.</p></div><div class="legacyx-credit-identity"><span>Client</span><strong><?php echo esc_html($u->display_name?:$u->user_login);?></strong><?php if($client):?><small><?php echo esc_html(get_post_meta($client->ID,'_legacyx_client_id',true));?></small><?php endif;?></div></header><?php if(!$client):?><div class="legacyx-portal-notice"><strong>Billing connection pending.</strong> Your Universal Client Profile must be linked before billing data can be displayed.</div><?php else:?><section class="legacyx-credit-summary"><div><span>Outstanding Balance</span><strong><?php echo esc_html(legacyx_money($counts['balance']));?></strong></div><div><span>Open Items</span><strong><?php echo esc_html($counts['open']);?></strong></div><div><span>Paid Items</span><strong><?php echo esc_html($counts['paid']);?></strong></div><div><span>Total Paid</span><strong><?php echo esc_html(legacyx_money($counts['paid_amount']));?></strong></div></section><section class="legacyx-credit-action"><span>Payment Security</span><p>Legacy X Firm OS does not display or store full card numbers, bank credentials or CVVs. Payments should be completed only through an authorized payment-provider link supplied on an invoice.</p></section><section class="legacyx-credit-track"><div class="legacyx-track-title"><span>BILLING HISTORY</span><h2>Invoices & Payments</h2><p>Only billing records assigned to your Universal Client Profile are shown here.</p></div><div class="legacyx-step-list"><?php if(!$rows):?><article class="legacyx-credit-step"><span class="legacyx-step-num">—</span><div><h3>No billing records yet</h3><p>Your invoices, retainers, service fees and payment history will appear here when added by the Legacy X Firm team.</p></div></article><?php else:foreach($rows as $i=>$r):$status=get_post_meta($r->ID,'_legacyx_status',true);$num=get_post_meta($r->ID,'_legacyx_invoice_number',true);$due=get_post_meta($r->ID,'_legacyx_amount_due',true);$paid=get_post_meta($r->ID,'_legacyx_amount_paid',true);$date=get_post_meta($r->ID,'_legacyx_due_date',true);$desc=get_post_meta($r->ID,'_legacyx_description',true);$note=get_post_meta($r->ID,'_legacyx_note',true);$pay=get_post_meta($r->ID,'_legacyx_payment_url',true);?><article class="legacyx-credit-step"><span class="legacyx-step-num"><?php echo sprintf('%02d',$i+1);?></span><div><h3><?php echo esc_html(get_the_title($r));?></h3><p><?php if($num):?><strong>Invoice:</strong> <?php echo esc_html($num);?> · <?php endif;?><strong>Status:</strong> <?php echo esc_html($status?:'Draft');?> · <strong>Amount:</strong> <?php echo esc_html(legacyx_money($due));?> · <strong>Paid:</strong> <?php echo esc_html(legacyx_money($paid));?><?php if($date):?><br><strong>Due:</strong> <?php echo esc_html($date);?><?php endif;?><?php if($desc):?><br><?php echo esc_html($desc);?><?php endif;?><?php if($note):?><br><strong>Next Action:</strong> <?php echo esc_html($note);?><?php endif;?></p><?php if($pay&&in_array($status,array('Open','Partially Paid','Past Due'),true)):?><p><a class="legacyx-card-link" href="<?php echo esc_url($pay);?>" target="_blank" rel="noopener noreferrer">Pay through authorized provider →</a></p><?php endif;?></div><b><?php echo esc_html($status==='Paid'?'✓':'→');?></b></article><?php endforeach;endif;?></div></section><?php endif;?></div></main><?php get_footer();?>